// Storage-side monotonic fencing token check preventing zombie-leader writes (Java)
public final class FencedLedgerStore {
    private long maxSeenEpoch = 0L;

    public synchronized void applyWrite(long fencingToken, String key, String value) {
        if (fencingToken < maxSeenEpoch) {
            throw new IllegalStateException(
                "Stale fencing token " + fencingToken + " < watermark " + maxSeenEpoch
            );
        }
        maxSeenEpoch = fencingToken;
        // Commit mutation atomically to durable storage
    }
}
